; ============================================================================
; uart_tx.asm — LOOM UART transmitter, 8N1, 115200 baud @ 60 MHz
; ============================================================================
;
; PIN MAPPING (default LOOM pinout, see sw/examples/README.md)
;   TX  P[10] = uo_out[2]   output, idle high, 1 = mark
;       (ui/uo pins need no DIR setup; uo_out is always driven)
;
; THREAD: any single thread (demo_all uses t0).  Uses no uio pins.
;
; TIMING
;   One bit = CLOCK_HZ / BAUD = 60e6 / 115200 = 520.8333 cycles.
;   The bit clock is NOT generated by an instruction loop: every frame cell is
;   an event-scheduler entry.  `setp BAUD_DIV` (12.4 fixed point) makes the
;   hardware advance the event time by 520 + 13/16 cycles per `emit`, with the
;   fractional carry accumulated in hardware -> the frame is drift-free and
;   independent of instruction scheduling, other threads, and FIFO stalls.
;
;   BAUD_DIV = round(CLOCK_HZ * 16 / BAUD) = 8333 = 0x208D  -> 520.8125 cyc
;   baud error = (520.8125-520.8333)/520.8333 = -40 ppm  (crystal-class)
;
; HOST INTERFACE (byte stream, see host/demos/demo_all.py)
;   Host pushes one data byte with TX_PUSH(t0, byte) and rings the doorbell by
;   writing EVT bit 0 (WRITE_CSR 0x13 = 1).  Firmware idles in `evwait` (zero
;   issue slots burned) then transmits the byte.
;   No reply is queued in the thread TX FIFO; the wire is the output.
;
; FRAME
;   start(0) d0 d1 ... d7 stop(1), LSB first.  Exactly 10 event cells.
;   Back-to-back frames are legal: the next start is scheduled one bit period
;   after the stop cell.  After an idle gap the behind-schedule clamp restarts
;   the cell chain at TMR+1 (spec §3.1), so the first start bit is always
;   emitted, never lost.
;
; CYCLE BUDGET (one byte, 4-thread worst case)
;   cell emit rate           : 1 event / 520.8 cycles (queue depth 4 -> the
;                              thread stalls on EMIT, which is correct)
;   per byte on the wire     : 10 cells                       = 5208 cyc
;   CPU instructions / byte  : 6 + 8*7 + 4 = 66 word-issues; ~66-260 cycles
;                              depending on contention -> < 5 % of the byte time
;   E2E latency (host->wire): doorbell->start bit  = 1-2 cycles after `pull`
;                              pull return -> first emit = 1 cycle; the clamp
;                              puts the start edge 1 cycle later.
;
; SIZE: 26 instructions (< 128, fits the FF fallback build).
;
; ASSEMBLY
;   python -m sw.loom_asm sw/examples/uart_tx.asm -o uart_tx.hex \
;       --rom-words 128 --fill 0x02000000 --lst --sym
; Relocatable: every jump is PC-relative, so the host may place the image at
; any PMEM base address and set_pc(tid, base).
; ============================================================================

.equ CLOCK_HZ,  60000000
.equ BAUD,      115200

; 12.4 fixed-point bit period, rounded to nearest 1/16 cycle.
.equ BAUD_DIV,  (CLOCK_HZ * 16 + BAUD / 2) / BAUD

.equ TX_PIN,    0x0400          ; P[10] = uo_out[2]
.equ EVT_BIT,   0               ; host doorbell flag (one per byte)

; ----------------------------------------------------------------------------
start:
        set     TX_PIN          ; idle line = mark (1), OR-only: other pins safe
        setm    TX_PIN          ; this thread's events drive P[10] only
        setp    BAUD_DIV        ; hardware bit clock, drift-free 12.4
main:
        evwait  EVT_BIT         ; sleep until the host has queued a byte
        pull    r1              ; r1 = data byte (host TX_PUSH)
        movi    r0, 0
        emit    r0              ; cell 0: start bit = 0
        movi    r4, 8
        movi    r5, TX_PIN
bit_loop:
        mov     r2, r1
        andi    r2, 1           ; isolate LSB
        shl     r2, 10          ; 0/1 -> 0x0000/0x0400 pin vector value
        emit    r2              ; data cell, LSB first
        shr     r1, 1
        subi    r4, 1
        jnz     bit_loop
        movi    r2, TX_PIN
        emit    r2              ; cell 9: stop bit = 1
        jmp     main
